* 
{
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

:root 
{
    --orange: #f26522;
    --orange-hover: #ff7838;
    --text: #f3f5f8;
    --muted: #a6aeb9;
    --glass-top: rgba(48, 56, 66, 0.44);
    --glass-bottom: rgba(20, 26, 34, 0.56);
    --row-bg: rgba(255, 255, 255, 0.06);
    --chip-bg: rgba(255, 255, 255, 0.09);
    --line: rgba(255, 255, 255, 0.18);
    --line-bright: rgba(255, 255, 255, 0.34);
}

body 
{
    background-color: #0b0e14;
    color: var(--text);
    font-family: 'Montserrat', -apple-system, BlinkMacSystemFont, sans-serif;
    font-size: 12px;
    min-height: 100vh;
    margin: 0;
    padding: 0;
    -webkit-font-smoothing: antialiased;
}

button,
input 
{
    font-family: inherit;
}

.frame 
{
    width: 100%;
    min-height: 100vh;
    padding: 26px 32px 24px;
    background-color: #0b0e14;
    background-image:
        linear-gradient(to bottom, rgba(6, 8, 12, 0.38) 0%, rgba(6, 8, 12, 0) 28%, rgba(6, 8, 12, 0.05) 60%, rgba(6, 8, 12, 0.52) 100%),
        var(--space-bg, url("assets/background.jpg"));
    background-size: cover;
    background-position: center;
    background-attachment: fixed;

    display: grid;
    grid-template-columns: 1.05fr 1.15fr 1fr 265px;
    grid-template-rows: auto 1fr auto;
    grid-template-areas:
        "header  header  header    header"
        "stage   stage   stage     right"
        "fuel    comms   blackbox  right";
    gap: 14px;
}

.glass 
{
    background: linear-gradient(180deg, var(--glass-top) 0%, var(--glass-bottom) 100%);
    border: 1px solid var(--line);
    border-top-color: var(--line-bright);
    border-radius: 2px;
    backdrop-filter: blur(11px);
    -webkit-backdrop-filter: blur(11px);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.32);
}

.panel 
{
    padding: 12px 13px;
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.panel-title 
{
    font-size: 12.5px;
    font-weight: 400;
    color: #eaedf2;
    padding-bottom: 8px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.14);
}

.panel-header-row 
{
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-bottom: 8px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.14);
}

.panel-title.no-border 
{
    padding-bottom: 0;
    border-bottom: none;
}

.btn-small 
{
    padding: 4px 10px;
    font-size: 10.5px;
}

.btn-full 
{
    width: 100%;
    padding: 8px 14px;
}

.header-area 
{
    grid-area: header;
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.brand 
{
    font-size: 17px;
    font-weight: 800;
    letter-spacing: 0.06em;
    color: #ffffff;
}

.title-block h1 
{
    font-size: 22px;
    font-weight: 400;
    color: #ffffff;
    letter-spacing: 0.01em;
}

.title-block p 
{
    margin-top: 5px;
    font-size: 11.5px;
    color: var(--muted);
}

.stage 
{
    grid-area: stage;
    display: flex;
    align-items: flex-end;
    justify-content: flex-start;
    min-height: 250px;
}

.telemetry-card 
{
    width: 265px;
    padding: 12px 13px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.row-list 
{
    display: flex;
    flex-direction: column;
    gap: 5px;
}

.row 
{
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 8px;
    padding: 3px;
    background: var(--row-bg);
    border-radius: 1px;
}

.chip 
{
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: var(--chip-bg);
    padding: 5px 9px;
    font-size: 11px;
    font-weight: 400;
    color: #dcdfe6;
    white-space: nowrap;
}

.chip svg 
{
    width: 13px;
    height: 13px;
    fill: none;
    stroke: #cfd4dc;
    stroke-width: 1.8;
    stroke-linecap: round;
    stroke-linejoin: round;
    flex-shrink: 0;
}

.value 
{
    font-size: 11.5px;
    font-weight: 600;
    color: #ffffff;
    padding-right: 8px;
    text-align: right;
    white-space: nowrap;
}

.row-input 
{
    width: 100%;
    min-width: 0;
    background: rgba(0, 0, 0, 0.28);
    border: 1px solid rgba(255, 255, 255, 0.16);
    color: #ffffff;
    font-size: 11.5px;
    font-weight: 600;
    padding: 5px 8px;
    text-align: right;
    outline: none;
    border-radius: 1px;
}

.row-input.left-align 
{
    text-align: left;
    font-weight: 400;
}

.row-input:focus 
{
    border-color: var(--orange);
}

.btn-orange 
{
    background: var(--orange);
    border: none;
    color: #ffffff;
    font-size: 11px;
    font-weight: 500;
    padding: 6px 14px;
    border-radius: 2px;
    cursor: pointer;
    white-space: nowrap;
    transition: background 0.15s ease, opacity 0.15s ease;
}

.btn-orange:hover 
{
    background: var(--orange-hover);
}

.btn-orange.transmitting 
{
    animation: blink 0.65s infinite;
}

@keyframes blink 
{
    50% {opacity: 0.4;}
}

.right-col 
{
    grid-area: right;
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    gap: 12px;
}

#fuel-panel     {grid-area: fuel;}
#comms-panel    {grid-area: comms;}
#blackbox-panel {grid-area: blackbox;}

.meter-group 
{
    display: flex;
    flex-direction: column;
    gap: 5px;
}

.meter-head 
{
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    font-size: 11px;
    color: #d6dbe2;
}

.meter-head span:last-child 
{
    font-size: 13px;
    font-weight: 600;
    color: #ffffff;
}

.meter 
{
    height: 22px;
    background: repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.2) 0 2px, transparent 2px 5px);
}

.meter-fill 
{
    height: 100%;
    transition: width 0.35s ease;
}

.meter-fill.white  {background: repeating-linear-gradient(90deg, #eef2f6 0 2px, transparent 2px 5px);}
.meter-fill.yellow {background: repeating-linear-gradient(90deg, #cbbd42 0 2px, transparent 2px 5px);}
.meter-fill.orange {background: repeating-linear-gradient(90deg, #d95f25 0 2px, transparent 2px 5px);}

.dict-columns 
{
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    border-bottom: 1px solid rgba(255, 255, 255, 0.12);
    padding-bottom: 6px;
}

.dict-col 
{
    display: flex;
    flex-direction: column;
    gap: 2px;
    padding: 0 8px;
    border-left: 1px solid rgba(255, 255, 255, 0.16);
}

.dict-col:first-child 
{
    padding-left: 0;
    border-left: none;
}

.dict-label 
{
    font-size: 10px;
    color: var(--muted);
}

.dict-col strong 
{
    font-size: 11.5px;
    font-weight: 600;
    color: #ffffff;
}

.comms-log 
{
    flex: 1;
    min-height: 92px;
    max-height: 115px;
    overflow-y: auto;
    padding: 8px;
    background:
        repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.06) 0 1px, transparent 1px 5px),
        rgba(0, 0, 0, 0.18);
    display: flex;
    flex-direction: column;
    gap: 5px;
}

.log-entry 
{
    font-family: 'JetBrains Mono', monospace;
    font-size: 11px;
    line-height: 1.4;
    color: #e8ecf2;
    word-break: break-word;
}

.log-entry.error 
{
    color: #ff8a65;
}

.comms-input-row 
{
    display: flex;
    gap: 6px;
}

.blackbox-pre 
{
    flex: 1;
    min-height: 155px;
    max-height: 185px;
    overflow-y: auto;
    padding: 8px 10px;
    background:
        repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.04) 0 1px, transparent 1px 5px),
        rgba(0, 0, 0, 0.2);
    font-family: 'JetBrains Mono', monospace;
    font-size: 10.5px;
    line-height: 1.48;
    color: #dde2ea;
    white-space: pre-wrap;
}

.comms-log::-webkit-scrollbar,
.blackbox-pre::-webkit-scrollbar 
{
    width: 5px;
}

.comms-log::-webkit-scrollbar-track,
.blackbox-pre::-webkit-scrollbar-track 
{
    background: rgba(0, 0, 0, 0.2);
}

.comms-log::-webkit-scrollbar-thumb,
.blackbox-pre::-webkit-scrollbar-thumb 
{
    background: rgba(255, 255, 255, 0.22);
    border-radius: 2px;
}

@media (max-width: 980px) 
{
    .frame 
    {
        grid-template-columns: 1fr;
        grid-template-areas:
            "header"
            "stage"
            "right"
            "fuel"
            "comms"
            "blackbox";
    }

    .stage 
    {
        min-height: 0;
    }

    .telemetry-card 
    {
        width: 100%;
    }
}

:root { --space-bg: url(data:image/jpeg;base64,); }
